import { useCallback, useEffect, useState } from 'react'
import { api } from '../api'
import ItemModal from './ItemModal'

const KINDS = [
  ['agent', 'Agent Tasks', 'Add Task'],
  ['qa', 'QA Test Cases', 'Add Test Case'],
]
const STATUS = { todo: 'To Do', doing: 'Doing', done: 'Done' }

// Agent Tasks and QA Test Cases of an approved ticket, generated by Claude and editable.
export default function ItemsSection({ card, onModal }) {
  const [items, setItems] = useState([])
  const [editing, setEditing] = useState(null) // null | {kind} (new) | item
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [split, setSplit] = useState('')

  const load = useCallback(async () => {
    if (!card?.id) return
    try {
      setItems(await api(`/api/cards/${card.id}/items`))
    } catch (err) {
      setError(err.message)
    }
  }, [card?.id])
  useEffect(() => { load() }, [load])

  const open = (v) => { setEditing(v); onModal(!!v) }

  async function generate() {
    if (items.length && !window.confirm('Replace the current tasks and test cases with a new set from Claude?')) return
    setBusy(true)
    setError('')
    setSplit('')
    try {
      const r = await api(`/api/cards/${card.id}/generate-items`, { method: 'POST', body: {} })
      if (r.split) setSplit(r.reason || 'This ticket is too big. Split it into smaller tickets.')
      else setItems(r.items)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }

  if (!card?.approved && items.length === 0) {
    return (
      <div className="field">
        <span>Agent Tasks &amp; QA Test Cases</span>
        <p className="hint">Approve the ticket and Claude drafts the tasks and test cases.</p>
      </div>
    )
  }

  return (
    <>
      <div className="field-row">
        <span className="items-title">Agent Tasks &amp; QA Test Cases</span>
        {card.approved && (
          <button type="button" className="ai-btn" disabled={busy} onClick={generate}>
            <span aria-hidden="true">✦</span> {items.length ? 'Regenerate' : 'Generate'}
          </button>
        )}
      </div>
      {busy && <p className="muted prompt-status"><span className="spinner" /> Claude is breaking the ticket down…</p>}
      {error && <p className="error">{error}</p>}
      {split && <div className="review-comment work"><div className="review-comment-head">Too Big For One Ticket</div><p>{split}</p></div>}
      {KINDS.map(([kind, label, add]) => (
        <div className="field" key={kind}>
          <div className="field-row">
            <span>{label}</span>
            <button type="button" className="ai-btn" onClick={() => open({ kind })}>+ {add}</button>
          </div>
          <ul className="flow-list">
            {items.filter((i) => i.kind === kind).map((i) => (
              <li key={i.id}>
                <button type="button" onClick={() => open(i)}>
                  <span>{i.title}</span>
                  {i.version > 0 && i.version < card.contentVersion && (
                    <span className="item-status stale" title="The ticket changed after Claude generated this. Regenerate to refresh.">Outdated</span>
                  )}
                  <span className={'item-status ' + i.status}>{STATUS[i.status]}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ))}
      {editing && (
        <ItemModal
          cardId={card.id}
          item={editing.id ? editing : null}
          kind={editing.kind}
          onSaved={() => { open(null); load() }}
          onDeleted={() => { open(null); load() }}
          onClose={() => open(null)}
        />
      )}
    </>
  )
}
